export function canonicalRevision16Text(text: string): string {
  for (let index = 0; index < text.length; index += 1) {
    const code = text.charCodeAt(index)
    if (code >= 0xd800 && code <= 0xdbff) {
      const next = text.charCodeAt(index + 1)
      if (!(next >= 0xdc00 && next <= 0xdfff)) throw new Error('invalid_unicode')
      index += 1
    } else if (code >= 0xdc00 && code <= 0xdfff) throw new Error('invalid_unicode')
  }
  return text.normalize('NFC').replace(/\s+/gu, ' ').trim()
}

export function countRevision16Words(text: string): number {
  const normalized = canonicalRevision16Text(text)
  return normalized ? normalized.split(' ').length : 0
}
